import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Posts with Multiple Photos or Videos","description":"Create, order, scan, view, and manage carousel posts in Foldergram.","frontmatter":{"title":"Posts with Multiple Photos or Videos","description":"Create, order, scan, view, and manage carousel posts in Foldergram."},"headers":[],"relativePath":"carousel-posts.md","filePath":"carousel-posts.md","lastUpdated":1791131065000}'),n={name:"carousel-posts.md"};function o(r,e,d,l,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="posts-with-multiple-photos-or-videos" tabindex="-1">Posts with Multiple Photos or Videos <a class="header-anchor" href="#posts-with-multiple-photos-or-videos" aria-label="Permalink to &quot;Posts with Multiple Photos or Videos&quot;">​</a></h1><p>A carousel is one swipeable post containing 2–20 supported images, animated images, videos, or a mixture of them. It has one caption and one set of like, save, collection, trash, delete, and sharing actions.</p><h2 id="folder-structure" tabindex="-1">Folder structure <a class="header-anchor" href="#folder-structure" aria-label="Permalink to &quot;Folder structure&quot;">​</a></h2><p>Create a reserved <code>carousels</code> folder directly inside an App Folder. Each immediate child is one post, and its media must be directly inside that child.</p><p>One carousel beside ordinary posts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gallery/</span></span>
<span class="line"><span>  AnimalPlanet/</span></span>
<span class="line"><span>    cover.jpg</span></span>
<span class="line"><span>    ordinary-post.jpg</span></span>
<span class="line"><span>    carousels/</span></span>
<span class="line"><span>      Lions/</span></span>
<span class="line"><span>        01-cover.jpg</span></span>
<span class="line"><span>        02-clip.mp4</span></span>
<span class="line"><span>        03-pride.jpg</span></span></code></pre></div><p>Multiple and mixed-media carousels:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gallery/</span></span>
<span class="line"><span>  Trips/</span></span>
<span class="line"><span>    carousels/</span></span>
<span class="line"><span>      Coast/</span></span>
<span class="line"><span>        01-arrival.jpg</span></span>
<span class="line"><span>        02-waves.mp4</span></span>
<span class="line"><span>      City Night/</span></span>
<span class="line"><span>        sign.gif</span></span>
<span class="line"><span>        street.jpg</span></span>
<span class="line"><span>        train.webm</span></span></code></pre></div><p>An App Folder may contain only carousel posts; no placeholder file is required directly inside it. <code>carousels</code> and its post children do not appear as separate App Folders in reserved mode.</p><h2 id="filename-ordering" tabindex="-1">Filename ordering <a class="header-anchor" href="#filename-ordering" aria-label="Permalink to &quot;Filename ordering&quot;">​</a></h2><p>Items use a case-insensitive natural filename sort, so <code>2-photo.jpg</code> sorts before <code>10-photo.jpg</code>. Numeric prefixes are optional; use zero-padded prefixes such as <code>01-</code>, <code>02-</code>, and <code>03-</code> only when you want to make the intended order explicit. The first item becomes the post cover in feeds and grids.</p><p>Renaming files can reorder a post after the next scan without replacing its caption, likes, or saved state. If more than 20 supported files exist, Foldergram uses the first 20 after sorting and reports a warning.</p><h2 id="renaming-and-moving-carousel-posts" tabindex="-1">Renaming and moving carousel posts <a class="header-anchor" href="#renaming-and-moving-carousel-posts" aria-label="Permalink to &quot;Renaming and moving carousel posts&quot;">​</a></h2><p>You can rename a carousel child folder and add, remove, or replace slides before running a full scan. Foldergram preserves the post ID, caption, likes, saved state, collection membership, and sort date when surviving indexed slides identify one existing post, remain together in one destination, and its old directory is gone. Safe slide matching requires unchanged file size and modification time. If every slide is replaced or no slide can be matched safely, post identity may not be preserved.</p><p>If surviving slides from one indexed post are split between carousel directories, the scan stops with an ambiguity error and preserves the existing post memberships. Keep those slides together in one carousel directory and run <strong>Scan Library</strong> again. Permission and I/O failures also stop the scan rather than treating an inaccessible carousel directory as missing; restore access and retry.</p><p>Use a directory name that has not been indexed when renaming a carousel. Foldergram does not merge two indexed post histories. When a destination&#39;s media or slide membership changes and file size and modification time match slides from another indexed post whose old files are missing, the scan reports a conflict before replacing destination image records, including when filenames overlap. If a conflict is reported, move the renamed carousel to a directory name that has not been indexed, then scan again; post identity can be preserved only when surviving slides can be matched safely to one existing post.</p><p>A replacement that has exactly the same paths, sizes, and modification times as the indexed destination cannot be distinguished from an unchanged destination. Detection is also limited when all incoming files have been modified and no longer match the source index.</p><h2 id="covers-and-avatars" tabindex="-1">Covers and avatars <a class="header-anchor" href="#covers-and-avatars" aria-label="Permalink to &quot;Covers and avatars&quot;">​</a></h2><p>The carousel cover and App Folder cover are separate:</p><ul><li>A carousel always uses its first item. A first-position video uses its generated poster.</li><li>A manually selected App Folder cover has first priority.</li><li>A direct <code>cover.*</code> file inside the App Folder is next.</li><li>Otherwise, the representative item from the newest visible post is used.</li></ul><p>Use <strong>Set as folder cover</strong> in the post viewer to select the currently active carousel item.</p><h2 id="captions-and-actions" tabindex="-1">Captions and actions <a class="header-anchor" href="#captions-and-actions" aria-label="Permalink to &quot;Captions and actions&quot;">​</a></h2><p>A carousel has one editable caption. Without a custom caption, the display-safe carousel child-folder name is shown, such as <code>Lions</code>, even when anonymous-public responses redact the underlying source path. Likes, saves, collection membership, trash, restore, and deletion apply to the whole post, never to one item.</p><p>In the viewer, Download original, Open original, dimensions, file size, format, EXIF details, and Set as folder cover follow the active item. Deleting a carousel permanently removes all included originals and generated derivatives.</p><p>Carousel photos and videos fit within the same viewer layout as single posts. Wide and tall slides keep their proportions, with black space where needed, and switching slides does not resize the viewer. Feed cards use the first slide&#39;s aspect ratio.</p><h2 id="item-ordering" tabindex="-1">Item ordering <a class="header-anchor" href="#item-ordering" aria-label="Permalink to &quot;Item ordering&quot;">​</a></h2><p>Carousel slides are sorted deterministically using natural numeric filename comparison. Numbers embedded in filenames sort numerically (e.g. <code>slide1.jpg</code>, <code>slide2.jpg</code>, <code>slide10.jpg</code>). Case variants and Unicode accents use canonical Unicode NFKD normalization and deterministic code-point tie breaking, ensuring the identical slide sequence across discovery runs and platforms.</p><h2 id="search-behavior-and-deduplication" tabindex="-1">Search behavior and deduplication <a class="header-anchor" href="#search-behavior-and-deduplication" aria-label="Permalink to &quot;Search behavior and deduplication&quot;">​</a></h2><p>When searching for media in the feed, queries match against filenames, captions, and folder paths across all carousel slides. If multiple slides in a carousel match the search query, the carousel appears exactly once in search results, ranked by the highest-scoring matching slide. The first position (representative slide) is displayed as the cover card, and pagination remains stable without duplicate posts across page boundaries.</p><h2 id="reels-and-mixed-videos" tabindex="-1">Reels and mixed videos <a class="header-anchor" href="#reels-and-mixed-videos" aria-label="Permalink to &quot;Reels and mixed videos&quot;">​</a></h2><p>Videos play inside the carousel using the integrated video player with interactive timeline scrubbing, play/pause controls, mute toggling, and optional HD source switching. In the post viewer, the active video starts automatically. When a browser blocks audible autoplay, Foldergram retries muted and updates the shared video mute preference so playback can begin without another click. The HD button appears only when the original video is larger than the generated preview and uses a browser-supported direct playback format (<code>playbackStrategy: &#39;original&#39;</code>). Toggling HD switches resolution without resetting current playback time or playing state.</p><p>Swiping or navigating through slides isolates video controls so that dragging the time slider or tapping player buttons does not trigger slide changes, and unmounting or switching slides pauses background playback cleanly.</p><p>Videos inside multi-item carousels do not appear in Reels or contribute to Reels counts. A child folder with exactly one video becomes a normal single-video post, so that fallback post may appear in Reels.</p><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source state</th><th>Result</th></tr></thead><tbody><tr><td>2–20 supported direct items</td><td>One carousel post.</td></tr><tr><td>Exactly one supported item</td><td>One normal single-item post plus a warning.</td></tr><tr><td>More than 20 supported items</td><td>First 20 are used; skipped items produce a warning and no derivatives.</td></tr><tr><td>Empty or unsupported-only child</td><td>Ignored without creating a post.</td></tr><tr><td>Hidden file or hidden child</td><td>Ignored.</td></tr><tr><td>Unsupported file beside supported media</td><td>Unsupported file is ignored.</td></tr><tr><td>Supported media directly inside <code>carousels</code></td><td>Ignored with a warning; put it in a child folder.</td></tr><tr><td>Valid child posts plus invalid root media</td><td>Valid posts are indexed and root media is warned about.</td></tr><tr><td>Supported media in a deeper nested folder</td><td>Nested media is ignored with a warning.</td></tr><tr><td><code>cover.jpg</code> inside a carousel child</td><td>Treated as an ordinary carousel item.</td></tr><tr><td>Two-item post loses one item</td><td>Same post becomes a single post and keeps its metadata.</td></tr><tr><td>One-item post gains another item</td><td>Same post becomes a carousel and keeps its metadata.</td></tr><tr><td>Child loses all supported items</td><td>Post is soft-deleted and can reactivate later.</td></tr><tr><td>Reserved folder has only invalid root media</td><td>No post or carousel-only App Folder is created.</td></tr></tbody></table><h2 id="settings-and-migration" tabindex="-1">Settings and migration <a class="header-anchor" href="#settings-and-migration" aria-label="Permalink to &quot;Settings and migration&quot;">​</a></h2><p>Reserved carousel mode is the default. In <strong>Settings → General Settings</strong>, turn on <strong>Treat carousels folders as normal app folders</strong> only when directories named <code>carousels</code> should use the legacy folder rules.</p><p>When there is no indexed <code>carousels</code> path conflict and no mode decision has been saved yet, General Settings shows a <strong>Carousel Posts</strong> announcement with an expandable directory example. Dismissing this informational card hides it permanently for the current browser and Foldergram origin. Clearing browser site data, using another browser profile, or opening Foldergram from another origin can show it again while the server-side mode decision remains pending.</p><p>When an existing index contains a <code>carousels</code> path segment, Settings presents a migration choice:</p><ul><li><strong>Use Carousel Posts</strong> enables the reserved structure.</li><li><strong>Keep Normal Folders</strong> preserves legacy folder discovery.</li></ul><p>Saving either choice stores the selected folder mode and resolves the migration decision. Settings keeps an update reminder visible until a successful full scan applies that mode to the index. Run <strong>Scan Library</strong> from <strong>Settings → Scan &amp; Library</strong> to update folders and posts. If the gallery location requires a new index, use <strong>Rebuild Library Index</strong> instead. The same follow-up applies whenever you change <strong>Treat carousels folders as normal app folders</strong>.</p><h2 id="scanning-and-media-processing" tabindex="-1">Scanning and media processing <a class="header-anchor" href="#scanning-and-media-processing" aria-label="Permalink to &quot;Scanning and media processing&quot;">​</a></h2><p>Scanning writes posts, ordered item membership, and asset metadata to SQLite. Pages read that index and do not scan the filesystem during requests. Each included item uses the normal thumbnail, preview, video-poster, and lazy-derivative behavior. No derivative work is scheduled for items skipped beyond the 20-item limit.</p><p>Structural problems complete the scan with warnings instead of reporting a processing failure. Review them in <strong>Settings → Scan &amp; Library</strong>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>App Folder is missing:</strong> ensure <code>carousels</code> has an immediate child containing at least one supported direct media file, then scan.</li><li><strong>Carousels appear as ordinary folders:</strong> turn off <strong>Treat carousels folders as normal app folders</strong>, save, then run <strong>Scan Library</strong>.</li><li><strong>Direct media is ignored:</strong> move it from <code>AppFolder/carousels</code> into <code>AppFolder/carousels/Post name</code>.</li><li><strong>Order is unexpected:</strong> use filename prefixes and rescan; dates and discovery order do not control item order.</li><li><strong>Only 20 items appear:</strong> this is the per-post limit; split the remaining files into another child folder.</li><li><strong>Nested items are missing:</strong> move them directly into the carousel child; nested discovery is intentionally disabled.</li><li><strong>An emptied carousel disappears:</strong> removing every supported item soft-deletes that post on the next scan; restoring items reactivates the same indexed post when its media identities can be reconciled.</li><li><strong>A video is absent from Reels:</strong> videos in a multi-item carousel are intentionally excluded.</li><li><strong>Caption fallback is unexpected:</strong> edit the shared caption or rename the carousel child and rescan.</li><li><strong>A scan failed with <code>UNIQUE constraint failed: post_items.image_id</code> after a rename:</strong> update Foldergram and run <strong>Scan Library</strong> again. Recovery without rebuilding requires surviving slides from one indexed post to remain together in one destination, with no competing indexed post at that path. If the scan reports split destinations or an existing-post conflict, follow <a href="#renaming-and-moving-carousel-posts">Renaming and moving carousel posts</a> before retrying.</li><li><strong>Cover is unexpected:</strong> position 1 controls the post cover; manual or direct <code>cover.*</code> rules control the App Folder avatar.</li><li><strong>Folder mode has not taken effect:</strong> follow the pending update message in <strong>Settings → Scan &amp; Library</strong>. Run <strong>Scan Library</strong>, or use <strong>Rebuild Library Index</strong> when Settings reports that a rebuild is required.</li></ul>`,46)])])}const u=s(n,[["render",o]]);export{g as __pageData,u as default};
